cypress_script:
describe('Sortable Data Tables', () => {
  it('should display the sortable data tables', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('h1').should('contain', 'Data Tables');
    cy.get('#table1').should('be.visible');
    cy.get('#table2').should('be.visible');
  });

  it('should not find an element that does not exist', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('#nonexistent').should('not.exist');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Sortable Data Tables', () => {
  test('should display the sortable data tables', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await page.locator('h1').isVisible();
    await page.locator('#table1').isVisible();
    await page.locator('#table2').isVisible();
  });

  test('should not find an element that does not exist', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    const nonexistent = await page.locator('#nonexistent').count();
    expect(nonexistent).toBe(0);
  });
});
